update_rule.pseudocode:
For each person i:
  base = Person[i].risk_perception
  // HA messaging
  if day >= campaign_start_day and Person[i] follows HA:
    ha_msg = campaign_intensity * ha_credibility * signal.risk_perceived_daily
  else:
    ha_msg = 0
  // Media messaging (average of followed outlets)
  media_msgs = []
  if Person[i] follows media:
    for each followed outlet m:
      tone = (message_bias + Normal(0, media_bias_variance)) * media_credibility_mean
      tone = clamp(tone, 0, 1)
      media_msgs.append(media_message_frequency * tone * signal.risk_perceived_daily)
  media_msg = mean(media_msgs) if media_msgs not empty else 0
  // Update risk perception (DeGroot-style with decay to prior)
  target = clamp(ha_msg + media_msg, 0, 1)
  Person[i].risk_perception = clamp((1 - message_decay_rate) * base + trust_update_rate * target + (message_decay_rate - trust_update_rate) * base, 0, 1)
  // Update trust in authorities slightly toward HA credibility if following HA
  if Person[i] follows HA:
    Person[i].trust_in_authorities = clamp(Person[i].trust_in_authorities + 0.5 * trust_update_rate * (ha_credibility - Person[i].trust_in_authorities), 0, 1)

policy_active = (day >= mandate_start_day)
For each location L:
  if policy_active:
    L.mask_policy = mandate_strictness
    L.enforcement_strength = enforcement_strength
  else:
    L.mask_policy = 0
    L.enforcement_strength = 0
  policy_pressure[L] = L.mask_policy
// Enforcement sampling
actions = 0
available = enforcement_resources
For each location L where L.mask_policy > 0 and available > 0:
  // sample non-compliant present persons (from interactions module occupancy list)
  S = sample_non_compliant_agents_in_L()
  for person i in S:
    p_enforce = enforcement_probability_scale * L.enforcement_strength
    if rand() < p_enforce and available > 0:
      actions += 1; available -= 1
      // Apply penalty as utility cost and increase future compliance propensity
      Person[i].cost_sensitivity = clamp(Person[i].cost_sensitivity + enforcement_warning_effect, 0, 1)
      // Optional: add fine cost to economic module budget (not tracked explicitly)
emit signal.enforcement_actions_today = actions
emit signal.policy_pressure_by_location = policy_pressure

// Restock stores periodically
if day % supply_restock_period == 0:
  for each store S:
    S.mask_stock += supply_restock_quantity_per_store
    S.mask_price = max(0.1, mask_price * (1 + store_markup))
// Household purchases/replacements
for each person i:
  need = (not Person[i].access_to_masks) or (day % max(1, round(mask_replacement_interval_mean)) == 0)
  if need:
    affordability = 1 / (1 + exp( (S.mask_price - 0.01 * Person[i].income) * (1 + Person[i].cost_sensitivity) ))
    // demand elasticity modifiers
    price_factor = exp(price_elasticity_mask_demand * S.mask_price)
    income_factor = exp(income_elasticity_mask_demand * log(max(1, Person[i].income)))
    p_buy = clamp(access_to_masks_initial_prob * affordability * price_factor * income_factor, 0, 1)
    if S.mask_stock > 0 and rand() < p_buy:
      S.mask_stock -= 1
      Person[i].access_to_masks = True

Initialize occupancy_by_location = empty map
For each person i:
  schedule = determine_day_schedule(i, work_participation_rate, school_participation_rate)
  visited_locations = [home, (work or school), (optionally store), (optionally transport)]
  for each visited location L in visited_locations:
    occupancy_by_location[L].append(i)
// Generate interactions per location
both_masked = 0; total_contacts = 0
for each location L:
  occupants = occupancy_by_location[L]
  // number of contacts ~ Poisson(lambda = contact_weight_L * peer_interaction_rate_per_day * |occupants|)
  K = Poisson(contact_weight_L * peer_interaction_rate_per_day * max(1, len(occupants)))
  for c in 1..K:
    i,j = sample_two_distinct(occupants)
    total_contacts += 1
    if Person[i].mask_adoption_state and Person[j].mask_adoption_state:
      both_masked += 1
emit signal.both_masked_contact_share_daily = (both_masked / max(1, total_contacts))
emit signal.daily_contacts = total_contacts
emit signal.occupancy_by_location = occupancy_by_location
